if (format === 'ruff') {
  try {
    const parsed = JSON.parse(output);
    if (Array.isArray(parsed)) {
      return parsed.map((entry: Record<string, unknown>) => ({
        file: String(entry.filename || ''),
        line: Number((entry.location as Array<Record<string, unknown>>)?.[0]?.row ?? entry.cell?.row ?? 0),
        column: Number(entry.column || 0) || undefined,
        severity: String(entry.severity || entry.code ? 'error' : 'warning'),
        ruleId: String(entry.code || ''),
        message: String(entry.message || ''),
        raw: JSON.stringify(entry),
      }));
    }
  } catch {
    // fall through to generic parser
  }
} else if (format === 'eslint') { ... }

const linterLocations = new Set<string>();
for (const result of linterResults) {
  for (const finding of result.findings) {
    const normalized = path.relative(workDir, path.resolve(workDir, finding.file));
    linterLocations.add(`${normalized}:${finding.line}`);
  }
}

const filtered = issues.filter((issue) => {
  const normalized = path.relative(workDir, path.resolve(workDir, issue.file));
  const key = `${normalized}:${issue.line}`;
  if (linterLocations.has(key)) {
    core.debug(`Suppressing AI finding at ${key} — matches linter output`);
    return false;
  }
  return true;
});

const filtered = issues.filter((issue) => {
  const key = `${issue.file}:${issue.line}`;
  if (linterLocations.has(key)) {
    const linterFinding = linterResults.flatMap(r => r.findings).find(f => `${f.file}:${f.line}` === key);
    if (linterFinding && issue.message.toLowerCase().includes(linterFinding.message.toLowerCase().slice(0, 20))) {
      core.debug(`Suppressing AI finding at ${key} — matches linter output`);
      return false;
    }
  }
  return true;
});

if (stderr) {
  const truncated = stderr.length > 500 ? stderr.slice(0, 500) + '...' : stderr;
  core.debug(`Linter "${result.tool}" stderr: ${truncated}`);
}
